const SB = 'https://cslqdvufvgsxnpwenilc.supabase.co';
return $input.all().map((item, index) => {
  const $json = item.json;
  const payload = ({eventKey:$('Contexto WhatsApp').first().json.event_key,kind:"cancel",index:$json.operation_index??0,payload:{}});
  const batch = ['stage','confirm_all'].includes(payload.kind);
  const args = batch ? {p_event_key:payload.eventKey,p_kind:payload.kind,p_items:payload.payload ?? []}
    : {p_event_key:payload.eventKey,p_kind:payload.kind,p_index:payload.index ?? 0,p_payload:payload.payload ?? {}};
  return {json:{url:SB+'/rest/v1/rpc/'+(batch?'whatsapp_batch':'whatsapp_operation'),body:JSON.stringify(args)},pairedItem:{item:index}};
});

